<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {Search,Download,RefreshCw} from '@lucide/vue';
defineProps<{staff:any}>();const emit=defineEmits(['unauthorized']);
const quarters=ref<any[]>([]),nextQuarter=ref<string|null>(null),quarterId=ref(''),versions=ref<any[]>([]),nextVersion=ref<number|null>(null),resultId=ref(''),clinics=ref<any[]>([]),doctors=ref<any[]>([]),clinicId=ref(''),doctorId=ref(''),groupBy=ref('clinic'),includeDetails=ref(false),report=ref<any>(null),lastExport=ref<any>(null),sourceLimit=ref(50),busy=ref(false),error=ref(''),notice=ref('');
const states:Record<string,string>={confirmed:'已正式确认',pending_review:'待总部复核',returned:'已退回'},short=(s:string)=>s?.slice(0,8).toUpperCase(),full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未确认';
const visibleDoctors=computed(()=>Array.from(new Map(doctors.value.filter(d=>!clinicId.value||d.clinicId===clinicId.value).map(d=>[d.doctorId,d])).values()));
class ApiError extends Error{constructor(public status:number,m:string){super(m);}}
async function api(path:string,body?:any){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),20000);try{const r=await fetch('/api/v1/quarter'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:ctrl.signal});const b=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401)emit('unauthorized');throw new ApiError(r.status,b.message||'查询或导出失败。');}return b;}finally{clearTimeout(timer);}}
const explain=(e:any)=>e instanceof Error?e.message:'操作失败。';
function invalidate(){report.value=null;lastExport.value=null;sourceLimit.value=50;notice.value='筛选已改变，请重新查询后导出。';}
function clinicChanged(){doctorId.value='';invalidate();}
async function catalog(more=false){busy.value=true;error.value='';try{const r=await api('/reports/catalog'+(more&&nextQuarter.value?'?after='+nextQuarter.value:''));quarters.value=more?[...quarters.value,...r.items]:r.items;nextQuarter.value=r.next;if(!quarterId.value&&quarters.value.length)quarterId.value=quarters.value[0].quarter_id;}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function loadOptions(more=false){const r=await api('/'+quarterId.value+'/report-options'+(more&&nextVersion.value?'?beforeVersion='+nextVersion.value:''));versions.value=more?[...versions.value,...r.versions]:r.versions;nextVersion.value=r.nextVersion;clinics.value=r.clinics;doctors.value=r.doctors;return r;}
async function moreVersions(){busy.value=true;error.value='';try{await loadOptions(true);}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function chooseQuarter(){busy.value=true;error.value='';invalidate();try{const o=await loadOptions();resultId.value=o.preferredResultId||'';clinicId.value='';doctorId.value='';}catch(e){error.value=explain(e);}finally{busy.value=false;}if(!error.value)await query();}
function filters(){return{resultId:resultId.value||null,clinicId:clinicId.value||null,doctorId:doctorId.value||null};}
async function query(){if(!quarterId.value)return;busy.value=true;error.value='';report.value=null;lastExport.value=null;try{const q=new URLSearchParams();for(const[k,v]of Object.entries(filters()))if(v)q.set(k,v);report.value=await api('/'+quarterId.value+'/report?'+q.toString());resultId.value=report.value.result?.id||'';sourceLimit.value=50;notice.value='已按当前权限读取所选版本与范围。';}catch(e){error.value=explain(e);}finally{busy.value=false;}}
async function download(){if(!report.value?.result)return;busy.value=true;error.value='';try{const file=await api('/'+quarterId.value+'/report/export',{...filters(),resultId:report.value.result.id,viewToken:report.value.viewToken,groupBy:groupBy.value,includeDetails:includeDetails.value});const bytes=new TextEncoder().encode(file.content),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');if(digest!==file.sha256)throw new Error('文件摘要不一致，未发起下载，请重新查询。');const url=URL.createObjectURL(new Blob([bytes],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=file.filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);lastExport.value=file;notice.value='CSV已生成并发起本机下载；实际下载结果请查看浏览器。';}catch(e){error.value=explain(e);lastExport.value=null;}finally{busy.value=false;}}
async function refresh(){if(!quarters.value.length){await catalog();if(quarterId.value)await chooseQuarter();return;}busy.value=true;error.value='';try{await loadOptions();}catch(e){error.value=explain(e);}finally{busy.value=false;}if(!error.value)await query();}
onMounted(async()=>{await catalog();if(quarterId.value)await chooseQuarter();});defineExpose({refresh});
</script>
<template><div class="qr-workspace"><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div>
 <section class="b-card qr-block"><div class="qr-head"><div><h2>季度结果查询与导出</h2><p>按已保存版本供阅，筛选不改变整批复核范围。</p></div><button class="b-button outline" :disabled="busy" @click="refresh"><RefreshCw :size="16"/>刷新查询</button></div>
 <div class="qr-filters"><label>核算季度<select v-model="quarterId" :disabled="busy" @change="chooseQuarter"><option v-for="q in quarters" :key="q.quarter_id" :value="q.quarter_id">{{q.quarter_label}}</option></select></label><label>结果版本<select v-model="resultId" :disabled="busy" @change="invalidate"><option v-if="!versions.length" value="">尚未形成结果</option><option v-if="report?.result && !versions.some(v=>v.result_id===report.result.id)" :value="report.result.id">第{{report.result.version}}版 · {{states[report.result.state]}}</option><option v-for="v in versions" :key="v.result_id" :value="v.result_id">第{{v.version_no}}版 · {{states[v.review_state]}}</option></select></label><label>查询诊所<select v-model="clinicId" :disabled="busy" @change="clinicChanged"><option value="">全部有权查看的诊所</option><option v-for="c in clinics" :key="c.clinicId" :value="c.clinicId">{{c.name}}</option></select></label><label>查询牙医<select v-model="doctorId" :disabled="busy" @change="invalidate"><option value="">全部原范围牙医</option><option v-for="d in visibleDoctors" :key="d.doctorId" :value="d.doctorId">{{d.name}}</option></select></label></div>
 <div class="qr-actions"><button class="b-button" :disabled="busy||!quarterId" @click="query"><Search :size="17"/>查询所选范围</button><button v-if="nextQuarter" class="f-text" :disabled="busy" @click="catalog(true)">加载更早季度</button><button v-if="nextVersion" class="f-text" :disabled="busy" @click="moreVersions">加载更早结果版本</button></div><p v-if="!quarters.length&&!busy">当前没有有权查看的核算季度。</p></section>
 <template v-if="report"><section v-if="!report.result" class="b-card qr-block"><h2>{{report.quarter.label}}尚未形成结果</h2><p>没有结果不等于零业绩，当前不生成结果合计或导出文件。</p></section><template v-else>
 <section class="b-card qr-block"><div class="qr-head"><div><div class="b-eyebrow">{{report.quarter.label}} · {{report.quarter.timeZone}}</div><h2>第{{report.result.version}}版{{report.result.adjusted?' · 调整版':''}}</h2><p>{{report.filters.scopeLabel}}</p></div><span class="b-pill" :class="report.result.state==='confirmed'?'active':''">整批：{{states[report.result.state]}}</span></div><p v-if="report.result.state!=='confirmed'" class="b-alert warning">此版本尚未正式确认，不能作为已确认季度业绩。</p><p v-else class="qr-version-note">{{report.result.isLatestConfirmed?'查询时最新已确认结果':'历史已确认结果，使用当时的来源及分配'}}</p><p>本版确认：{{full(report.result.confirmedAt)}}<br/>首次全范围确认：{{full(report.quarter.firstConfirmedAt)}}</p><p v-if="report.comparison==='changed'" class="b-alert warning">所选范围的当前来源已变化；下列金额仍按本版采用原版，不静默重算。</p><p v-if="report.comparison==='unavailable'" class="b-alert warning">当前来源对比未完成，仍按已保存版本供阅；不据此宣称与当前资料一致。</p>
 <div class="qr-metrics"><article><span>实收收入</span><strong>{{report.projection.totals.income}}</strong></article><article><span>材料成本</span><strong>{{report.projection.totals.cost}}</strong></article><article><span>分配费用</span><strong>{{report.projection.totals.expense}}</strong></article><article><span>经营贡献</span><strong>{{report.projection.totals.contribution}}</strong></article></div><p class="b-help">单位：元。经营贡献＝实收收入−材料成本−分配费用，不等于工资。合计仅包含本次筛选，不重复累计跨店分项。</p>
 <label class="qr-group">结果展示<select v-model="groupBy" :disabled="busy"><option value="clinic">牙医在诊所的分项</option><option value="doctor">牙医在所选诊所的跨店合计</option></select></label><div class="q-table-wrap"><table><thead><tr><th>牙医</th><th>诊所范围</th><th>实收收入</th><th>材料成本</th><th>分配费用</th><th>经营贡献</th></tr></thead><tbody><tr v-for="l in groupBy==='clinic'?report.projection.lines:report.projection.byDoctor" :key="l.doctorId+(l.clinicId||'all')"><td>{{l.doctorName}}</td><td>{{groupBy==='clinic'?l.clinicName:l.clinics.map((c:any)=>c.clinicName).join('、')}}</td><td>{{l.income}}</td><td>{{l.cost}}</td><td>{{l.expense}}</td><td><strong>{{l.contribution}}</strong></td></tr></tbody></table></div><div v-if="!doctorId" class="qr-unassigned"><strong>未归属牙医的诊所商品实收：{{report.projection.unassignedTotal}}元</strong><p>独立保留为所选诊所收入，不混入某位牙医的上述收入或经营贡献。</p><p v-for="u in report.projection.unassigned" :key="u.sourceId">{{u.clinicName}} · {{short(u.sourceId)}} · {{u.amount}}元</p></div></section>
 <section class="b-card qr-block"><details><summary>展开本版采用来源与核实依据（{{report.projection.sources.length}}条归集）</summary><p class="b-help">同一原来源可能分配多项，合计以本次归集金额为准。只展示所选诊所和牙医的归集，不带病历正文或联系方式。</p><article v-for="(s,i) in report.projection.sources.slice(0,sourceLimit)" :key="i" class="qr-source"><strong>{{s.kindName}} · {{s.clinicName}} · {{s.doctorName}}</strong><p>{{s.label}}<br/>来源{{short(s.sourceId)}} · 采用原版{{s.version}}（{{short(s.revisionId)}}） · {{s.occurredAt?.length===10?s.occurredAt:full(s.occurredAt)}}</p><p>原来源金额{{s.sourceAmount}}元 · 本次归集{{s.allocatedAmount}}元</p><p>{{s.basis}}</p></article><p v-if="!report.projection.sources.length">本版没有采用来源，零值按保存时明确核实的原范围结果显示。</p><button v-if="report.projection.sources.length>sourceLimit" class="b-button outline" @click="sourceLimit+=50">显示后续依据（当前{{sourceLimit}}/{{report.projection.sources.length}}）</button></details></section>
 <section class="b-card qr-block"><div class="qr-head"><div><h2>导出当前查询范围</h2><p>导出第{{report.result.version}}版 · {{report.filters.scopeLabel}}。金额、状态和明细采用同一版本。</p></div><button class="b-button" :disabled="busy" @click="download"><Download :size="17"/>生成并下载CSV</button></div><label class="b-checkbox"><input v-model="includeDetails" type="checkbox" :disabled="busy"/><span>包含当前范围的采用来源及核实依据</span></label><p class="b-help">按上方展示方式导出分项或跨店合计，不把两者重复相加。CSV为UTF-8文本，保留两位金额与版本、状态和时间。</p><div v-if="lastExport" class="qr-export"><strong>{{lastExport.filename}}</strong><p>已生成{{lastExport.rowCount}}行，其中依据{{lastExport.detailCount}}行 · {{full(lastExport.generatedAt)}}</p><small>生成记录：{{short(lastExport.exportId)}} · 文件摘要：{{lastExport.sha256}}</small></div></section>
 </template></template>
</div></template>
<style scoped>
.qr-block{padding:26px;margin:20px 0}.qr-block h2{font-size:21px;margin:0 0 10px}.qr-block p{font-size:14px;line-height:1.8;color:#728478;overflow-wrap:anywhere}.qr-head{display:flex;align-items:center;justify-content:space-between;gap:20px}.qr-head>div{min-width:0}.qr-head>.b-button{flex-shrink:0}.qr-filters{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0}.qr-actions{display:flex;gap:18px;align-items:center;flex-wrap:wrap}.qr-version-note{padding:10px 16px;background:#eff5eb;border-radius:8px}.qr-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:22px 0}.qr-metrics article{background:#f3f7ef;border:1px solid #e5eddf;border-radius:10px;padding:18px;min-width:0}.qr-metrics span{display:block;font-size:13px;color:#819177;margin-bottom:10px}.qr-metrics strong{font-size:24px;color:#345a47;overflow-wrap:anywhere}.qr-group{max-width:380px;margin-top:20px}.qr-unassigned,.qr-export{padding:18px;background:#f2f6e9;border-radius:10px;font-size:14px}.qr-export small{font-size:12px;overflow-wrap:anywhere;color:#718365}.qr-block summary{cursor:pointer;font-size:15px;color:#3c7056;line-height:1.7}.qr-source{padding:18px 0;border-bottom:1px solid #e1e9df;font-size:14px}.qr-source p{margin:5px 0}.qr-block .b-alert{overflow-wrap:anywhere}@media(max-width:760px){.qr-block{padding:18px}.qr-head{flex-direction:column;align-items:start;gap:12px}.qr-filters{grid-template-columns:1fr}.qr-metrics{grid-template-columns:1fr 1fr}.qr-metrics article{padding:14px}.qr-metrics strong{font-size:21px}}
</style>
